8^2 \left[ \cos^2 \left( \frac{\pi}{8} \right)  + \cos^2 \left( \frac{3\pi}{16} \right) - \cos^2 \left( \frac{\pi}{8} \right) \right] \left[ \cos^2 \left( \frac{\pi}{16} \right) \right]
